SELECT @@version,@@global.innodb_use_native_aio; SELECT enterprise_id,OCTET_LENGTH(display_name) AS bytes,CHAR_LENGTH(display_name) AS scalars,OCTET_LENGTH(CONVERT(display_name USING utf16)) DIV 2 AS utf16_units,status FROM enterprise_identity ORDER BY enterprise_id; SELECT id,OCTET_LENGTH(config_manifest) AS bytes,CHAR_LENGTH(config_manifest) AS scalars,OCTET_LENGTH(CONVERT(config_manifest USING utf16)) DIV 2 AS utf16_units,SHA2(config_manifest,256) AS sha256 FROM transcription_input ORDER BY id;
